arguments.command:
cat > tests/book_test.sh <<'E'
#!/bin/bash
fail=0
f=$(mktemp)
out=$(BOOKINGS=$f bash bin/book A 0900 1000 standup)
[ "$out" = "booked A 0900-1000" ] || { echo "book output"; fail=1; }
[ "$(wc -l < "$f")" -eq 1 ] || { echo "book appends"; fail=1; }
rm -f "$f"

# overlap rules
f=$(mktemp)
BOOKINGS=$f bash bin/book A 0900 1000 one >/dev/null
BOOKINGS=$f bash bin/book A 0930 1030 overlap >/dev/null 2>&1 && { echo "overlap accepted"; fail=1; }
BOOKINGS=$f bash bin/book A 0800 1100 enclosing >/dev/null 2>&1 && { echo "enclosing accepted"; fail=1; }
BOOKINGS=$f bash bin/book A 0900 1000 same >/dev/null 2>&1 && { echo "identical accepted"; fail=1; }
[ "$(wc -l < "$f")" -eq 1 ] || { echo "rejected must not write"; fail=1; }
BOOKINGS=$f bash bin/book A 1000 1100 adjacent >/dev/null 2>&1 || { echo "adjacent rejected"; fail=1; }
BOOKINGS=$f bash bin/book A 0800 0900 before >/dev/null 2>&1 || { echo "adjacent-before rejected"; fail=1; }
BOOKINGS=$f bash bin/book B 0900 1000 other >/dev/null 2>&1 || { echo "other room rejected"; fail=1; }
[ "$(wc -l < "$f")" -eq 4 ] || { echo "line count"; fail=1; }
rm -f "$f"
exit $fail
E
bash scripts/verify.sh; echo "red=$?"

